#!/usr/bin/env bash
# Grant the macOS desktop build outbound network access.
#
# The Flutter macOS app is sandboxed and blocks all network connections by
# default, so connecting to your gpix server fails with:
#   SocketException: Connection failed (OS Error: Operation not permitted, errno = 1)
# Adding `com.apple.security.network.client` to the entitlements fixes it.
#
# The macos/ folder is generated by `flutter create` (and git-ignored), so run
# this once after generating it, from the app/ directory:
#   bash tool/setup_macos.sh
set -euo pipefail

cd "$(dirname "$0")/.."

patched=0
for f in macos/Runner/DebugProfile.entitlements macos/Runner/Release.entitlements; do
  if [ ! -f "$f" ]; then
    echo "skip: $f not found — run 'flutter create --platforms=macos --org com.gpix --project-name gpix_app .' first"
    continue
  fi
  /usr/libexec/PlistBuddy -c "Add :com.apple.security.network.client bool true" "$f" 2>/dev/null \
    || /usr/libexec/PlistBuddy -c "Set :com.apple.security.network.client true" "$f"
  echo "patched: $f"
  patched=1
done

if [ "$patched" = "1" ]; then
  echo "Done. Now (re)start the app:  flutter run -d macos"
fi
